import sqlite3
import json
from pymilvus import connections, Collection
from neo4j import GraphDatabase
import numpy as np
from sentence_transformers import SentenceTransformer

# Initialize sentence transformer for embedding queries
model = SentenceTransformer('all-MiniLM-L6-v2')

# Database paths and configurations
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


def get_tampa_hotels():
    conn = sqlite3.connect(sqlite_paths['business'])
    cursor = conn.cursor()
    cursor.execute("""
        SELECT business_id, name, address, stars, review_count, attributes 
        FROM business 
        WHERE city = ? AND categories LIKE ?
    """, ('Tampa', '%Hotels%'))
    rows = cursor.fetchall()
    conn.close()
    hotels = []
    for row in rows:
        attr_str = row[5]
        attributes = {}
        if attr_str:
            try:
                # Clean and parse JSON-like string
                attr_str = attr_str.replace("'", '"').replace("True", "true").replace("False", "false")
                attributes = json.loads(attr_str)
            except:
                attributes = {}
        hotels.append({
            'business_id': row[0],
            'name': row[1],
            'address': row[2],
            'stars': row[3],
            'review_count': row[4],
            'attributes': attributes
        })
    return hotels


def get_good_for_kids_hotels(hotels):
    return [h for h in hotels if h['attributes'].get('GoodForKids') == 'True']


def connect_milvus():
    connections.connect(host=milvus_config['milvus_host'], port=milvus_config['milvus_port'])


def semantic_search_milvus(collection_name, query_text, top_k=50):
    collection = Collection(collection_name)
    query_embedding = model.encode([query_text])
    search_params = {"metric_type": "L2", "params": {"nprobe": 10}}
    results = collection.search(
        data=query_embedding,
        anns_field="embedding",
        param=search_params,
        limit=top_k,
        output_fields=["business_id"]
    )
    business_ids = []
    for hits in results:
        for hit in hits:
            business_ids.append(hit.entity.get('business_id'))
    return business_ids


def get_neo4j_co_reviews(hotel_ids):
    driver = GraphDatabase.driver(neo4j_config['neo4j_uri'], auth=neo4j_config['neo4j_auth'])
    with driver.session() as session:
        result = session.run(
            "MATCH (b:Business)-[:HAS_REVIEW]->(r:Review) WHERE b.business_id IN $hotel_ids RETURN b.business_id, count(r) AS review_count",
            hotel_ids=hotel_ids
        )
        return {record['b.business_id']: record['review_count'] for record in result}


def main():
    try:
        # Step 1: Get Tampa hotels
        tampa_hotels = get_tampa_hotels()
        if not tampa_hotels:
            print("No hotels found in Tampa.")
            return

        # Step 3: Filter by GoodForKids attribute
        good_for_kids = get_good_for_kids_hotels(tampa_hotels)
        good_for_kids_ids = {h['business_id'] for h in good_for_kids}

        # Step 2: Semantic search in reviews and tips
        connect_milvus()
        query = "family-friendly hotel with good amenities for children"
        review_ids = semantic_search_milvus(milvus_config['milvus_collections']['reviews'], query)
        tip_ids = semantic_search_milvus(milvus_config['milvus_collections']['tips'], query)
        semantic_ids = set(review_ids + tip_ids)

        # Combine: hotels that are either GoodForKids or mentioned in semantic search
        candidate_ids = good_for_kids_ids.union(semantic_ids)
        candidate_hotels = [h for h in tampa_hotels if h['business_id'] in candidate_ids]

        # Optional Step 4: Enhance with Neo4j co-review counts
        try:
            co_review_counts = get_neo4j_co_reviews(list(candidate_ids))
            for h in candidate_hotels:
                h['co_review_count'] = co_review_counts.get(h['business_id'], 0)
        except Exception as e:
            print(f"Neo4j step failed (optional): {e}")
            for h in candidate_hotels:
                h['co_review_count'] = 0

        # Step 5: Rank results
        # Score: prioritize GoodForKids, then stars, review_count, and co_review_count
        def rank_score(hotel):
            base = hotel['stars'] * 10 + hotel['review_count'] * 0.1 + hotel['co_review_count'] * 0.05
            if hotel['business_id'] in good_for_kids_ids:
                base += 20  # boost for explicit GoodForKids
            return base

        ranked_hotels = sorted(candidate_hotels, key=rank_score, reverse=True)

        # Output top 10
        print("Top family-friendly hotels in Tampa:")
        for i, hotel in enumerate(ranked_hotels[:10], 1):
            print(f"{i}. {hotel['name']} - {hotel['address']} (Stars: {hotel['stars']}, Reviews: {hotel['review_count']})")

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
